  61	\begin{lemma}[Level of the axis-parallel line map]\label{lem:ld-aline-level}
  62		\lean{MIPStarRE.QPBT.isCondLinear_ldALineCL}
  63		\leanok
  64		\uses{def:ld-question-distribution, def:cl-func, lem:cl-concat}
  65		Fix $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game}. The map $L_{\mathsf{ALine}}$ of Equation~\eqref{eq:cl-alnf} is a $2$-level conditionally linear function on $V$.
  66	\end{lemma}
  67	\begin{proof}
  68		\leanok
  69		\uses{def:cl-func, lem:cl-concat, def:line-representative}
  70		$L_{\mathsf{ALine}}$ is the concatenation of the $1$-level CL function projecting $V_I \oplus V_V$ onto $V_I$ with the family $\{L^{\mathrm{Ln}}_{e_i}\}_{i \in \{1,\ldots,m\}}$ of $1$-level CL functions on $V_X$, selected by $i = \chi(s)$; by Lemma~\ref{lem:cl-concat} the concatenation is $1+1 = 2$-level conditionally linear.
  71	\end{proof}
  72	
  73	\begin{lemma}[Level of the diagonal line map]\label{lem:ld-dline-level}
  74		\lean{MIPStarRE.QPBT.isCondLinear_ldDLineCL}
  75		\leanok
  76		\uses{def:ld-question-distribution, def:cl-func, lem:cl-concat}
  77		Fix $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game}. The map $L_{\mathsf{DLine}}$ of Equation~\eqref{eq:cl-dlnf} is a $3$-level conditionally linear function on $V$.
  78	\end{lemma}
  79	\begin{proof}
  80		\leanok
  81		\uses{def:cl-func, lem:cl-concat, def:line-representative}
  82		$L_{\mathsf{DLine}}$ is the concatenation of the identity on $V_I$, of the family $v \mapsto \pi_{i-1}(v)$ of $1$-level CL functions on $V_V$ indexed by $i = \chi(s)$, and of the family $L^{\mathrm{Ln}}_{v'}$ of $1$-level CL functions on $V_X$ indexed by the pair $(s,v')$; by Lemma~\ref{lem:cl-concat} the concatenation is $1+1+1 = 3$-level conditionally linear.
  83	\end{proof}
