 85	\begin{lemma}[The low-degree question distribution is a typed CL distribution]\label{lem:ld-question-typed-cl}
 86		\lean{MIPStarRE.QPBT.ldQuestionDistribution_eq_typedCL}
 87		\leanok
 88		\uses{def:ld-question-distribution, def:typed-cl-distributions, def:graph-distribution, lem:ld-aline-level, lem:ld-dline-level}
 89		Fix $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game}, let $L = \{L_t\}_{t \in \mathcal T^{\mathrm{ld}}}$ be the family of Definition~\ref{def:ld-question-distribution}, and let $G^{\mathrm{ld}}$ be the graph on $\mathcal T^{\mathrm{ld}}$ all of whose unordered pairs, self-loops included, are edges. Then the question distribution of $\mathfrak{G}^{\mathrm{ld}}$ is the $(\mathcal T^{\mathrm{ld}}, G^{\mathrm{ld}})$-typed conditionally linear distribution $\mu^{G^{\mathrm{ld}}}_{L,\,L}$ of Definition~\ref{def:typed-cl-distributions}.
 90	\end{lemma}
 91	\begin{proof}
 92		\leanok
 93		\uses{def:typed-cl-distributions, def:graph-distribution, def:cl-dist}
 94		Every unordered pair of types is an edge of $G^{\mathrm{ld}}$, so the graph distribution $\mu_{G^{\mathrm{ld}}}$ of Definition~\ref{def:graph-distribution} is the uniform distribution on $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$. For each ordered type pair $(t_{\mathrm A}, t_{\mathrm B})$ the CL distribution $\mu_{L_{t_{\mathrm A}},\, L_{t_{\mathrm B}}}$ is the push-forward of the uniform distribution on $V$ along $z \mapsto \bigl(L_{t_{\mathrm A}}(z), L_{t_{\mathrm B}}(z)\bigr)$. Binding the uniform type pair to these push-forwards and tagging each content with its type is exactly the two-stage sampling procedure of Definition~\ref{def:ld-question-distribution}.
 95	\end{proof}
