275	\section{The Magic Square game}
276	% Paper label sec:ms kept for cross-reference fidelity.
277	\label{sec:ms}
278	
279	We recall the Magic Square game of Mermin and Peres. It is a simple self-test for two EPR pairs, and it allows one to test that a pair of binary observables \emph{anticommutes}; both properties are used in the Pauli basis test. Here it is presented as a binary constraint satisfaction game. Throughout this section and the next, $\sigma^X$ and $\sigma^Z$ denote the single-qubit Pauli observables, with associated two-outcome projective measurements $\{\sigma^W_b\}_{b \in \F_2}$ for $W \in \{X,Z\}$.
280	
281	\begin{definition}[The Magic Square game]\label{def:ms-game}
282		\uses{def:game, def:graph-distribution}
283		The Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ is the following two-player game. There are $9$ variables $x_1,\ldots,x_9$ taking values in $\F_2$, arranged in a $3 \times 3$ grid: the cell in row $r$ and column $c$ contains the variable $x_{3(r-1)+c}$. There are $6$ linear equations over these variables: for each of the three rows and each of the first two columns, the sum of the three variables in it equals $0$; for the third column, the sum of the three variables in it equals $1$.
284	
285		The question types are
286		\begin{align*}
287			\mathcal T^{\mathrm{mc}} &= \{\mathsf{Constraint}_i : i = 1,2,\ldots,6\}\;,\\
288			\mathcal T^{\mathrm{mv}} &= \{\mathsf{Variable}_j : j = 1,2,\ldots,9\}\;,\\
289			\mathcal T^{\mathrm{ms}} &= \mathcal T^{\mathrm{mc}} \cup \mathcal T^{\mathrm{mv}}\;,
290		\end{align*}
291		where $\mathsf{Constraint}_i$ for $i \in \{1,2,3\}$ denotes the constraint of row $i$ (with variables $x_{3(i-1)+1}, x_{3(i-1)+2}, x_{3(i-1)+3}$), $\mathsf{Constraint}_4$ and $\mathsf{Constraint}_5$ denote the constraints of the first two columns, and $\mathsf{Constraint}_6$ denotes the constraint of the third column (with variables $x_{i-3}, x_{i}, x_{i+3}$ for $\mathsf{Constraint}_i$, $i \in \{4,5,6\}$).
292	
293		The question distribution is as follows: the verifier samples $\mathsf{Constraint}_i$ uniformly from $\mathcal T^{\mathrm{mc}}$, then samples $\mathsf{Variable}_j$ uniformly among the three variables appearing in the row or column of $\mathsf{Constraint}_i$; one player, chosen uniformly at random, receives $\mathsf{Constraint}_i$ and the other receives $\mathsf{Variable}_j$. Equivalently, the verifier samples a uniformly random edge of the bipartite \emph{type graph} $G^{\mathrm{ms}}$ on vertex sets $\mathcal T^{\mathrm{mc}}$ and $\mathcal T^{\mathrm{mv}}$, whose edges are $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{3(i-1)+j}$ for $i,j \in \{1,2,3\}$ and $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{(i-3)+3(j-1)}$ for $i \in \{4,5,6\}$, $j \in \{1,2,3\}$ ($18$ edges in total, and no self-loops), and sends one endpoint to a uniformly random player and the other endpoint to the other player.
294	
295		The $\mathsf{Constraint}$ player answers with three bits $(\beta_{v_1}, \beta_{v_2}, \beta_{v_3}) \in \F_2^3$, where $(v_1,v_2,v_3)$ are the indices of the three variables of $\mathsf{Constraint}_i$; the $\mathsf{Variable}$ player answers with a single bit $\gamma \in \F_2$. The players win if and only if the $\mathsf{Constraint}$ player's answer satisfies the equation associated with $\mathsf{Constraint}_i$ and $\gamma = \beta_j$.
296	\end{definition}
297	
298	The following theorem records the self-testing (rigidity) properties of the Magic Square game. It is used in the soundness analysis of the Pauli basis test to enforce anticommutation relations between certain pairs of observables.
299	With zero-based labels, the paper's variables $1$ and $5$ have labels $0$ and
300	$4$, respectively.
301	
302	\begin{theorem}[Rigidity of the Magic Square game]\label{thm:ms-rigidity}
303		\lean{MIPStarRE.QPBT.exists_ms_rigidity}
304		\leanok
305		\uses{def:ms-game, def:tensor-product-value, def:EPR, def:povm-distance}
306		Let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy that succeeds in the Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ with probability $1-\eps$, where $\ket{\psi} \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$. Then there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\hilb_{\mathrm A'}, \hilb_{\mathrm B'} \cong (\C^2)^{\ot 2}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''}$ are finite dimensional, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A''} \ot \hilb_{\mathrm B''}$, such that:
307		\begin{enumerate}
308			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket{\psi} - \ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}} \bigr\| \le O(\sqrt\eps)$;
309			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$,
310			\begin{align*}
311				\tilde A^{\mathsf{Variable}_1}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^X_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
312				\tilde A^{\mathsf{Variable}_5}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^Z_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
313				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^X_b)_{\mathrm B'}\;,\\
314				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^Z_b)_{\mathrm B'}\;,
315			\end{align*}
475		\end{itemize}
476		The win predicate $D^{\mathrm{pauli}} = D^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A, \mathrm B\}$ and $W \in \{X,Z\}$; in all cases where no action is indicated, the predicate accepts. In the last four clauses, the content of the player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ is a tuple $(u_X, u_Z, r_X, r_Z)$, from which the predicate first computes
477		\begin{equation}
478			\label{eq:gamma-value}
479			\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
480		\end{equation}
481		where $\mathrm{ind}_m(\cdot) \in \F_q^M$ is the indicator vector of the low-degree encoding (Chapter~\ref{chap:qpbt-algebra}), the inner dot denotes the dot product on $\F_q^M$, and $\tr\colon \F_q \to \F_2$ is the finite-field trace.
482		\begin{enumerate}
483			\item (\textbf{Consistency check}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
484			\item (\textbf{Low-degree check}) Let $\mathsf{ldparams} = (q,m,d,1)$; admissibility of $\mathsf{qldparams}$ gives $d \ge 1$ and $m \mid q$, so this is a parameter tuple as in Definition~\ref{def:ld-game}.
485			\begin{enumerate}
486				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{ALine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{ALine}, x_{\overline w}, a_w, a_{\overline w})$.
487				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{DLine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{DLine}, x_{\overline w}, a_w, a_{\overline w})$.
488			\end{enumerate}
489			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
490			\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
491			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
492			\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
493			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
494		\end{enumerate}
495		The game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
496	\end{definition}
497	
498	Note the one-sided gating on $\gamma$: the commutation check and the $\mathsf{Pair}$ consistency check accept automatically when $\gamma \neq 0$, while the Magic Square check and the $\mathsf{Variable}$ consistency check accept automatically when $\gamma = 0$.
